import { chromium } from 'playwright';
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

// Renders the SVG illustrations in src/demo/assets/ to the formats Quip serves images in, and writes them into
// src/demo/images.ts (base64, so the demo account needs no files at run time, in the extension or in Node).
// The diagrams are PNG and the picture is JPEG, as a photo would be. The generated file is committed;
// run this only after changing an SVG.
//
// Usage: npm run demo-assets (needs the Chromium of `npm run e2e`)
const root = fileURLToPath(new URL('..', import.meta.url));
const dir = `${root}src/demo/assets/`;
const FORMAT = { 'lisbon-sunset': 'jpeg' };
const WIDTH = 800;
const HEIGHT = 450;

const browser = await chromium.launch({ channel: 'chromium' });
const images = [];
try {
  const page = await browser.newPage({ viewport: { width: WIDTH, height: HEIGHT }, deviceScaleFactor: 1 });
  for (const file of (await readdir(dir)).filter((f) => f.endsWith('.svg')).sort()) {
    const name = file.replace(/\.svg$/, '');
    const type = FORMAT[name] ?? 'png';
    const svg = (await readFile(`${dir}${file}`, 'utf8')).replace(/<svg /, `<svg style="width:${WIDTH}px;height:${HEIGHT}px" `);
    await page.setContent(`<!doctype html><body style="margin:0;background:#fff">${svg}</body>`);
    const bytes = await page.screenshot({ type, ...(type === 'jpeg' ? { quality: 88 } : {}), clip: { x: 0, y: 0, width: WIDTH, height: HEIGHT } });
    images.push({ file: `${name}.${type === 'jpeg' ? 'jpg' : 'png'}`, type: `image/${type}`, base64: bytes.toString('base64') });
    console.log(`${file} -> ${images.at(-1).file} (${bytes.length} bytes)`);
  }
} finally {
  await browser.close();
}

const out = [
  '// Generated by scripts/build-demo-assets.mjs from the SVG files in ./assets. Do not edit it by hand.',
  '// Pictures for the made-up demo account (account.ts), as base64.',
  'export const DEMO_IMAGES: Record<string, { type: string; base64: string }> = {',
  ...images.map((i) => `  '${i.file}': {\n    type: '${i.type}',\n    base64:\n      '${i.base64}',\n  },`),
  '};',
  '',
].join('\n');
await writeFile(`${root}src/demo/images.ts`, out);
console.log(`Wrote src/demo/images.ts (${(out.length / 1024).toFixed(0)} KB)`);
